if (ctx.deployment_id == null && ctx.project_id != null) {
  ctx.deployment_id = ctx.project_id;
}
if ((ctx.deployment_name == null || ctx.deployment_name == '') && ctx.project_name != null && ctx.project_name != '') {
  ctx.deployment_name = ctx.project_name;
}
if (ctx.deployment_type == null && ctx.project_type != null) {
  ctx.deployment_type = ctx.project_type;
}
if (ctx.total_ecu == null && ctx.total_chargeable_units != null) {
  ctx.total_ecu = ctx.total_chargeable_units;
}
ctx.remove('project_id');
ctx.remove('project_name');
ctx.remove('project_type');
ctx.remove('total_chargeable_units');
if (ctx['@timestamp'] != null && ctx.deployment_id != null) {
  ctx.composite_key = ZonedDateTime.parse(ctx['@timestamp']).toLocalDate().toString() + '_' + ctx.deployment_id;
}

def sku = ctx.sku;
if (sku == null) {
  ctx.cost_type = 'other';
  ctx.cost_category = 'other';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}

// Observability / Security SKUs (ingest GB vs retained storage).
if (sku.startsWith('observability.') || sku.startsWith('security.')) {
  if (sku.contains('retained') || sku.contains('storage') || sku.contains('retention')) {
    ctx.cost_type = 'retained';
    ctx.cost_category = 'data_tier';
    ctx.is_allocatable = true;
    ctx.allocation_driver = 'storage';
    return;
  }
  if (sku.contains('ingest') || sku.contains('logs') || sku.contains('metrics')
      || sku.contains('traces') || sku.contains('apm') || sku.contains('siem')) {
    ctx.cost_type = 'ingest';
    ctx.cost_category = 'data_tier';
    ctx.is_allocatable = true;
    ctx.allocation_driver = 'indexing';
    return;
  }
}

// Elasticsearch and Vector Database capacity (VCU + retained).
if (sku.startsWith('elasticsearch.') || sku.startsWith('vector.')
    || sku.startsWith('elasticsearch-vector.')) {
  if (sku.contains('-ingest-vcu_') || sku.contains('ingest-vcu')) {
    ctx.cost_type = 'ingest-vcu';
    ctx.cost_category = 'data_tier';
    ctx.is_allocatable = true;
    ctx.allocation_driver = 'indexing';
    return;
  }
  if (sku.contains('-search-vcu_') || sku.contains('search-vcu')) {
    ctx.cost_type = 'search-vcu';
    ctx.cost_category = 'data_tier';
    ctx.is_allocatable = true;
    ctx.allocation_driver = 'query';
    return;
  }
  if (sku.startsWith('elasticsearch.retained_') || sku.contains('retained_')
      || sku.contains('storage')) {
    ctx.cost_type = 'retained';
    ctx.cost_category = 'data_tier';
    ctx.is_allocatable = true;
    ctx.allocation_driver = 'storage';
    return;
  }
  if (sku.contains('-ml-vcu_') || sku.contains('ml-vcu')) {
    ctx.cost_type = 'ml-vcu';
    ctx.cost_category = 'platform';
    ctx.is_allocatable = false;
    ctx.allocation_driver = 'none';
    return;
  }
}

if (sku.startsWith('serverless.support-')) {
  ctx.cost_type = 'serverless_premium_support';
  ctx.cost_category = 'support';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}

if (ctx.cost_type == 'data-transfer' || sku.contains('data-transfer')
    || sku.contains('data-out') || sku.contains('egress')) {
  ctx.cost_type = 'data-transfer';
  ctx.cost_category = 'transfer';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (ctx.cost_type == 'snapshots' || sku.contains('snapshot')) {
  ctx.cost_type = 'snapshots';
  ctx.cost_category = 'snapshot';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (ctx.cost_type == 'inference' || sku.contains('inference') || sku.contains('llm')) {
  ctx.cost_type = 'inference';
  ctx.cost_category = 'platform';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (sku.contains('synthetics')) {
  ctx.cost_type = 'synthetics';
  ctx.cost_category = 'platform';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (sku.contains('workflow')) {
  ctx.cost_type = 'workflows';
  ctx.cost_category = 'platform';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (sku.contains('agent-builder')) {
  ctx.cost_type = 'agent-builder';
  ctx.cost_category = 'platform';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}
if (sku.contains('cross-project') || sku.contains('cps')) {
  ctx.cost_type = 'cross-project-search';
  ctx.cost_category = 'platform';
  ctx.is_allocatable = false;
  ctx.allocation_driver = 'none';
  return;
}

ctx.cost_category = 'other';
ctx.is_allocatable = false;
ctx.allocation_driver = 'none';
